// ═══════════════════════════════════════════════════════════
// LIVE DASHBOARD WEBSOCKET CLIENT (BROWSER)
// ═══════════════════════════════════════════════════════════
let dashboardWS = null;
let dashboardRetryCount = 0;
function connectDashboardWS() {
  if (dashboardWS && dashboardWS.readyState === 1) return;
  try {
    dashboardWS = new window.WebSocket('ws://localhost:8081');
    dashboardWS.onopen = () => {
      console.log('[Game] Connected to dashboard WebSocket');
      dashboardRetryCount = 0;
    };
    dashboardWS.onerror = () => {};
    dashboardWS.onclose = () => {
      dashboardRetryCount++;
      const delay = Math.min(1000 * Math.pow(2, dashboardRetryCount), 60000);
      setTimeout(connectDashboardWS, delay);
    };
  } catch (e) {
    dashboardRetryCount++;
    const delay = Math.min(1000 * Math.pow(2, dashboardRetryCount), 60000);
    setTimeout(connectDashboardWS, delay);
  }
}

function sendDashboardUpdate(type: string, bundle: any, snapshot: any) {
  if (dashboardWS && dashboardWS.readyState === 1) {
    if (type === 'event' && snapshot?.event) {
      dashboardWS.send(JSON.stringify({ type, event: snapshot.event }));
    } else if (type === 'shotDecision' && snapshot?.shotDecision) {
      dashboardWS.send(JSON.stringify({ type, shotDecision: snapshot.shotDecision }));
    } else if (type === 'passDecision' && snapshot?.passDecision) {
      dashboardWS.send(JSON.stringify({ type, passDecision: snapshot.passDecision }));
    } else {
      dashboardWS.send(JSON.stringify({ type, bundle, snapshot }));
    }
  }
}
window.sendDashboardUpdate = sendDashboardUpdate;
connectDashboardWS();

